export const translations: Record<string, any> = {
  EN, BN, AR, TR, DE, FR, ES, ZH, HI, RU, JA, KO, FA, IT, PT, UR, VI, TH, ID, NL, PL, SV, EL, MS, AF, AK
};

const allSupportedLangs = [
  "EN", "BN", "AR", "TR", "ES", "FR", "DE", "IT", "PT", "RU",
  "ZH", "JA", "KO", "HI", "ID", "MS", "VI", "TH", "NL", "PL",
  "SV", "NO", "FI", "DA", "EL", "HE", "CS", "HU", "RO", "UK",
  "SK", "BG", "HR", "LT", "LV", "ET", "SL", "MT", "IS", "GA",
  "SQ", "MK", "HY", "KA", "FA", "UR", "AF", "AK"
];

// Final processing of supported languages - ensured they exist in translations record
allSupportedLangs.forEach(lang => {
  if (!translations[lang]) {
    translations[lang] = EN;
  }
});

export type TranslationKey = keyof typeof EN;
export type LanguageCode = string;

/**
 * Robust translation lookup function
 */
export const getTranslation = (key: string, lang: string = 'EN', tone: Tone = 'corporate'): string => {
  try {
    const targetLang = lang || 'EN';
    const targetTone = tone || 'corporate';

    // 1. Check localized tone variations first (e.g., BN.hero_title.corporate)
    const localizedEntry = localizedToneVariants[targetLang]?.[key];
    if (localizedEntry) {
      if (typeof localizedEntry === 'string') return localizedEntry;
      const localizedTone = (localizedEntry as Record<Tone, string>)[targetTone];
      if (localizedTone) return localizedTone;
    }

    // 2. Check standard localized translations (e.g., AR.company)
    const localizedBase = translations[targetLang]?.[key];
    if (localizedBase && typeof localizedBase === 'string') return localizedBase;

    // 3. Fallback to global tone variants (defaults to EN)
    const globalTone = toneVariants[key]?.[targetTone];
    if (globalTone) return globalTone;

    // 4. Final fallback to English standard translation
    const enBase = translations['EN']?.[key];
    return (enBase && typeof enBase === 'string') ? enBase : key;
  } catch (error) {
    console.warn(`Translation error for key "${key}" in lang "${lang}":`, error);
    return typeof key === 'string' ? key : 'Translation Error';
  }
};
